def mock_validate_int_btwn(value, min, max):
    """
    Copied from the in-use validator so we can test values here.
    """
    if int(value) < min or int(value) > max:
        raise ValidationError(
            ("Please enter a number between %(min)s and %(max)s. The number %(value)s is not valid."),
            params={
                "value": value,
                "min": min,
                "max": max
            },
        )


def populate_flat_drawing_coordinates(apps, schema_editor):
    """
    Creates new dedicated coordinate objects for any FlatDrawings (fd's) with at least one full set of coordinates
    """
    FlatDrawing = apps.get_model("docsearch", "FlatDrawing")
    Coordinate = apps.get_model("docsearch", "Coordinate")

    # Only migrate coordinates if FlatDrawing has at least one full set
    has_coords_filter = (
        Q(section__isnull=False, area__isnull=False)
        | Q(cross_ref_section__isnull=False, cross_ref_area__isnull=False)
    )
    fds_with_coords = (
        FlatDrawing.objects
        .filter(has_coords_filter)
    )

    coords_to_create = []
    for fd in fds_with_coords:
        # One flat drawing can have both primary and secondary coords
        coordinate_values = [
            (fd.section,fd.area),
            (fd.cross_ref_section,fd.cross_ref_area)
        ]

        for i, section_area_pair in enumerate(coordinate_values):
            if not all(section_area_pair):
                continue

            # Only migrate coordinates if both values are *valid*
            try:
                section, area = section_area_pair
                mock_validate_int_btwn(section, 1, 36)
                mock_validate_int_btwn(area, 1, 33)
            except ValidationError as e:
                coords_label = "primary set" if i == 0 else "secondary set"
                logger.error(f"Error on FlatDrawing ID={fd.id} : {e}")
                logger.error(f"Skipping Coordinate creation for this FD's {coords_label}...")
                logger.info("======")
            else:
                coords_to_create.append(
                    Coordinate(
                        flat_drawing=fd,
                        section=section_area_pair[0],
                        area=section_area_pair[1]
                    )
                )

    Coordinate.objects.bulk_create(coords_to_create)
    logger.info(f"FlatDrawings touched: {len(fds_with_coords)}")
    logger.info(f"Coordinate objects created: {len(coords_to_create)}")


def destroy_coordinate_objects(apps, schema_editor):
    """
    Remove all coordinates when reversing this migration.
    """
    Coordinate = apps.get_model("docsearch", "Coordinate")
    Coordinate.objects.all().delete()
    logger.info("Coordinate objects deleted!")


